// Quick-reply chips shown above the input (ids of HELP_TOPICS).
export const QUICK_TOPIC_IDS = ['upload', 'image-type', 'result', 'doctors'];

/** Normalize user input for keyword matching. */
const normalize = (text) =>
  (text || '')
    .toLowerCase()
    .replace(/[.,!?;:"'()\[\]{}]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

/** Find the best topic for a free-text question (keyword scoring). */
export const matchTopic = (text) => {
  const q = normalize(text);
  if (!q) return null;
  let best = null;
  let bestScore = 0;
  for (const topic of HELP_TOPICS) {
    let score = 0;
    for (const kw of topic.keywords) {
      if (q.includes(normalize(kw))) {
        // Longer keyword matches are stronger signals.
        score += kw.length;
      }
    }
    if (score > bestScore) {
      best = topic;
      bestScore = score;
    }
  }
  return best;
};

/** Answer for a topic in the given language, falling back to English. */
export const getTopicAnswer = (topic, lang) => {
  if (!topic) return '';
  return topic.answer[lang] || topic.answer.en;
};

/** Topic display label in the given language, falling back to English. */
export const getTopicLabel = (topic, lang) => {
  if (!topic) return '';
  return topic.label[lang] || topic.label.en;
};

export const getChatUi = (lang) => CHAT_UI[lang] || CHAT_UI.en;
